const body = $input.first().json.body;
const required = ['candidate_name', 'role', 'stage'];
const missing = required.filter(f => !body[f]);
if (missing.length) return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
const stages = ['applied','phone_screen','technical','take_home','onsite','offer','hired','rejected','withdrawn'];
const stage = stages.includes(body.stage) ? body.stage : 'applied';
return [{ json: {
  valid: true,
  candidateId: body.candidate_id || `C-${Date.now()}`,
  candidateName: body.candidate_name.trim(),
  candidateEmail: body.candidate_email || '',
  role: body.role.trim(),
  department: body.department || '',
  stage,
  previousStage: body.previous_stage || '',
  interviewerNotes: (body.interviewer_notes || '').slice(0, 1000),
  rating: body.rating ? parseFloat(body.rating) : null,
  source: body.source || '',
  actionRequired: body.action_required || '',
  nextStepDate: body.next_step_date || '',
  hiringManagerEmail: body.hiring_manager_email || '',
  replyEmail: body.reply_email || null,
  loggedAt: new Date().toISOString()
} }];

const input = $('Validate Log').first().json;
const needsNote = input.interviewerNotes && input.interviewerNotes.length > 50;
const stageAdvances = input.previousStage && input.stage !== input.previousStage;
return [{ json: { input, needsNote, stageAdvances } }];

