const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let summary;
try { summary = JSON.parse(raw.replace(/```json|```/g,'').trim()); } catch(e) { summary = { summary: raw.slice(0, 300) }; }
const input = $('Check Note Needed').first().json.input;
return [{ json: { noteSummary: summary, input } }];

const rows = $input.all().map(r => r.json).filter(r => r.candidate_name && r.stage && !['hired','rejected','withdrawn'].includes(r.stage));
const byRole = {};
rows.forEach(r => { if (!byRole[r.role]) byRole[r.role] = []; byRole[r.role].push(r); });
const stageOrder = ['applied','phone_screen','technical','take_home','onsite','offer'];
const byStage = {};
rows.forEach(r => { if (!byStage[r.stage]) byStage[r.stage] = 0; byStage[r.stage]++; });
const actionNeeded = rows.filter(r => r.action_required || (r.next_step_date && new Date(r.next_step_date) <= new Date()));
return [{ json: { activeCandidates: rows.length, byRole, byStage, actionNeeded, generatedAt: new Date().toISOString() } }];

