const note = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
const d = $('Aggregate Pipeline').first().json;
function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
const stageLabels = {applied:'Applied',phone_screen:'Phone Screen',technical:'Technical',take_home:'Take Home',onsite:'Onsite',offer:'Offer'};
const stageBars = Object.entries(d.byStage).sort((a,b)=>(Object.keys(stageLabels).indexOf(a[0]))-(Object.keys(stageLabels).indexOf(b[0]))).map(([stage,count]) => `<div style="display:flex;align-items:center;gap:10px;padding:6px 0"><div style="font-size:13px;width:110px;color:#374151">${esc(stageLabels[stage]||stage)}</div><div style="background:#2563eb22;border-radius:4px;height:20px;flex:1"><div style="background:#2563eb;height:20px;border-radius:4px;width:${Math.min(100,count*20)}%;display:flex;align-items:center;padding-left:6px"><span style="font-size:11px;font-weight:700;color:#fff">${count}</span></div></div></div>`).join('');
const roleBlocks = Object.entries(d.byRole).map(([role, candidates]) => `<div style="padding:8px 0;border-bottom:1px solid #f3f4f6"><div style="font-size:14px;font-weight:600;margin-bottom:4px">${esc(role)} (${candidates.length})</div>${candidates.map(c=>`<div style="font-size:12px;color:#6b7280;padding:2px 0">${esc(c.candidate_name)} — ${esc(c.stage.replace(/_/g,' '))}${c.rating?' · '+c.rating+'/5':''}</div>`).join('')}</div>`).join('');
const actionRows = d.actionNeeded.slice(0,8).map(c => `<div style="font-size:13px;padding:6px 0;border-bottom:1px solid #fef2f2;color:#7f1d1d">⚡ ${esc(c.candidate_name)} (${esc(c.role)}): ${esc(c.action_required||'next step overdue')}</div>`).join('');
const html = `<!DOCTYPE html><html><head><meta charset="utf-8"></head><body style="margin:0;padding:16px;background:#f9fafb;font-family:sans-serif"><div style="max-width:660px;margin:0 auto"><div style="background:#1e293b;color:#fff;padding:18px 26px;border-radius:10px 10px 0 0"><div style="font-size:11px;text-transform:uppercase;color:#64748b">Weekly Hiring Pipeline · ${esc(d.generatedAt.split('T')[0])}</div><div style="font-size:18px;font-weight:700">${d.activeCandidates} active candidates · ${Object.keys(d.byRole).length} open roles</div></div><div style="background:#fff;padding:16px 26px;border:1px solid #e5e7eb;border-top:none"><p style="font-size:14px;line-height:1.7;color:#374151;margin:0">${esc(note)}</p></div><div style="background:#fff;padding:16px 26px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:8px">Stage distribution</div>${stageBars}</div>${actionRows?`<div style="background:#fef2f2;padding:14px 26px;border:1px solid #fecaca"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#b91c1c;margin-bottom:7px">Action needed</div>${actionRows}</div>`:''}<div style="background:#fff;padding:14px 26px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:8px">By role</div>${roleBlocks}</div></div></body></html>`;
return [{ json: { html, activeCandidates: d.activeCandidates } }];
